create table public.marketing_campaigns (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, name text not null, channel text not null check(channel in ('email','sms','push')), status text not null default 'draft' check(status in ('draft','scheduled','sending','sent','cancelled')), scheduled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.marketing_suppressions (store_id uuid not null references public.stores(id) on delete cascade, address text not null, channel text not null, reason text not null, created_at timestamptz not null default now(), primary key(store_id,address,channel));
